    for (i = 0; i < n; i++) {
        if (i % 20 == 0)
            fprintf(stderr, "\n");
        fprintf(stderr, "%0.6lf ", y[i]);
    }
    fprintf(stderr, "\nend   dump: %s\n", "y");
    fprintf(stderr, "==END   DUMP_ARRAYS==\n");
}

int main() {

    int n = 30;

    double alpha;
    double beta;
    double A[30][30];
    double B[30][30];
    double tmp[30];
    double x[30];
    double y[30];

    init_array(n, &alpha, &beta, A, B, x);

    kernel_gesummv(alpha, beta, A, B, tmp, x, y);

    print_array(n, y);

    return 0;
}
